patch:
diff --git a/src/path.mjs b/src/path.mjs
index 3f0e871..3b95706 100644
--- a/src/path.mjs
+++ b/src/path.mjs
@@ -1,5 +1,20 @@
-import { resolve } from "node:path";
+import { isAbsolute, relative, resolve, sep } from "node:path";

 export function resolveChild(root, child) {
-  return resolve(root, child);
+  if (isAbsolute(child)) {
+    throw new Error("Child path must be relative to root");
+  }
+
+  const resolved = resolve(root, child);
+  const relativePath = relative(root, resolved);
+  if (
+    relativePath === "" ||
+    relativePath === ".." ||
+    relativePath.startsWith(`..${sep}`) ||
+    isAbsolute(relativePath)
+  ) {
+    throw new Error("Child path must resolve inside root");
+  }
+
+  return resolved;
 }
